let subject;

const category = $('Feedback Category Router').first().json.category;
const topic = $('Feedback Category Router').first().json.topic;
const priority = $('Feedback Category Router').first().json.priority;

if (category === "Complaint") {

  if (priority === "Critical") {
    subject = `Important: We've Received Your ${topic} Concern`;
  } else {
    subject = `We've Received Your ${topic} Concern`;
  }

} else if (category === "Feature Request") {

  subject = `Thank You for Your ${topic} Suggestion`;

} else if (category === "Compliment") {

  subject = `Thank You for Your Feedback`;

} else {

  subject = `Thank You for Your Feedback`;
}

return [
  {
    json: {
      ...$json,
      email_subject: subject
    }
  }
];
